text = "4"
try:
    count = int(text)
except ValueError:
    print("정수로 입력하세요")
else:
    if count < 0:
        print("0 이상이어야 합니다")
    else:
        print("두 배:", count * 2)

total_text = "12"
count_text = "0"
try:
    total = int(total_text)
    count = int(count_text)
    result = total / count
except ValueError:
    print("두 값 모두 정수로 입력하세요")
except ZeroDivisionError:
    print("나누는 수는 0일 수 없습니다")
else:
    print("결과:", result)

